import{_ as t,c as r,o,a5 as i}from"./chunks/framework.DuCYAsAJ.js";const b=JSON.parse('{"title":"收藏与关注系统","description":"","frontmatter":{"title":"收藏与关注系统","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#4.3","branch":"main","level":1,"order":4.3},"headers":[],"relativePath":"posts/projects/zfeed/04-interaction-rpc-service/03-favorite-and-follow-systems.md","filePath":"posts/projects/zfeed/04-interaction-rpc-service/03-favorite-and-follow-systems.md","lastUpdated":1779632679000}'),a={name:"posts/projects/zfeed/04-interaction-rpc-service/03-favorite-and-follow-systems.md"};function n(c,e,l,p,f,g){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="收藏与关注系统" tabindex="-1">收藏与关注系统 <a class="header-anchor" href="#收藏与关注系统" aria-label="Permalink to &quot;收藏与关注系统&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/favoritelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/favoritelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/followuserlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/followuserlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/queryfavoriteinfologic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/queryfavoriteinfologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/removefavoritelogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/removefavoritelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/front/internal/logic/interaction/unfollowuserlogic.go" target="_blank" rel="noreferrer">app/front/internal/logic/interaction/unfollowuserlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/favorite_strategy.go" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/favorite_strategy.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/interaction/interaction.pb.go" target="_blank" rel="noreferrer">app/rpc/interaction/interaction/interaction.pb.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/do/favorite_do.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/do/favorite_do.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/queryfavoriteinfologic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/queryfavoriteinfologic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/real_store_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/real_store_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/removefavoritelogic.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/removefavoritelogic.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/model/interaction_model.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/model/interaction_model.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/favorite_repository.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/favorite_repository.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/mq_consume_dedup_repository_test.go" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/mq_consume_dedup_repository_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/proto/interaction.proto" target="_blank" rel="noreferrer">app/rpc/interaction/proto/interaction.proto</a></li></ul></details><p>收藏与关注系统是 <code>interaction-rpc</code> 服务中的核心社交组件。它们处理用户与内容、用户与用户之间的关系，并结合 MySQL 持久化存储、Redis 高速关系查询，以及 Transactional Outbox 模式，将事件可靠投递到 <code>count-rpc</code>、<code>content-rpc</code> 等下游服务。</p><h2 id="收藏系统架构" tabindex="-1">收藏系统架构 <a class="header-anchor" href="#收藏系统架构" aria-label="Permalink to &quot;收藏系统架构&quot;">​</a></h2><p>收藏系统允许用户保存文章、视频或评论。它维护双重状态：MySQL 中的主记录，以及 Redis 中用于快速判断“是否收藏”和支持基于 cursor 收藏 Feed 的缓存表示。</p><h3 id="数据流-收藏与取消收藏" tabindex="-1">数据流：收藏与取消收藏 <a class="header-anchor" href="#数据流-收藏与取消收藏" aria-label="Permalink to &quot;数据流：收藏与取消收藏&quot;">​</a></h3><p>当用户收藏一条内容时，系统会在数据库中执行幂等 <code>Upsert</code>，并在同一个事务内把事件记录到 <code>zfeed_favorite_event</code> 表。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic.go#L61-L104" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic.go#61-104</a></p><ol><li>目标所有者解析：写入前，系统通过 <code>resolveFavoriteTargetOwner</code> 解析内容所有者（文章/视频作者或评论作者）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic.go#L137-L158" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic.go#137-158</a></li><li>事务写入：<code>Favorite</code> 逻辑使用 MySQL 事务，确保收藏记录和 outbox 事件原子创建。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic.go#L61-L104" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic.go#61-104</a></li><li>缓存失效：数据库写入成功后，删除关系缓存（<code>fav:rel:{scene}:{user}:{content}</code>），防止读到旧值。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic.go#L113-L116" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic.go#113-116</a></li><li>Feed 更新：对于文章和视频，系统使用 Lua 脚本 <code>AddUserFavoriteIfExistsScript</code> 更新用户收藏 Feed 的 Redis ZSet；如果该 ZSet 存在，则维护它。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic.go#L122-L132" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic.go#122-132</a></li></ol><h3 id="收藏实体空间映射" tabindex="-1">收藏实体空间映射 <a class="header-anchor" href="#收藏实体空间映射" aria-label="Permalink to &quot;收藏实体空间映射&quot;">​</a></h3><table tabindex="0"><thead><tr><th>自然语言概念</th><th>代码实体</th><th>文件路径</th></tr></thead><tbody><tr><td>收藏记录</td><td><code>ZfeedFavorite</code></td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/model/interaction_model.go#L5-L16" target="_blank" rel="noreferrer">app/rpc/interaction/internal/model/interaction_model.go#5-16</a></td></tr><tr><td>收藏事件 Outbox</td><td><code>ZfeedFavoriteEvent</code></td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/model/interaction_model.go#L22-L35" target="_blank" rel="noreferrer">app/rpc/interaction/internal/model/interaction_model.go#22-35</a></td></tr><tr><td>收藏逻辑</td><td><code>FavoriteLogic</code></td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic.go#L22-L30" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic.go#22-30</a></td></tr><tr><td>收藏仓储</td><td><code>FavoriteRepository</code></td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/favorite_repository.go#L1-L20" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/favorite_repository.go#1-20</a></td></tr></tbody></table><h3 id="图-收藏事务流程" tabindex="-1">图：收藏事务流程 <a class="header-anchor" href="#图-收藏事务流程" aria-label="Permalink to &quot;图：收藏事务流程&quot;">​</a></h3><p>该图展示 gRPC 请求与事务持久化层之间的衔接。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic.go#L44-L135" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic.go#44-135</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/model/interaction_model.go#L5-L35" target="_blank" rel="noreferrer">app/rpc/interaction/internal/model/interaction_model.go#5-35</a></p><h2 id="关注系统与资料摘要" tabindex="-1">关注系统与资料摘要 <a class="header-anchor" href="#关注系统与资料摘要" aria-label="Permalink to &quot;关注系统与资料摘要&quot;">​</a></h2><p>关注系统管理用户之间的社交图谱。它支持关注、取消关注，以及用于个人资料页的批量查询。</p><h3 id="关注-取消关注逻辑" tabindex="-1">关注/取消关注逻辑 <a class="header-anchor" href="#关注-取消关注逻辑" aria-label="Permalink to &quot;关注/取消关注逻辑&quot;">​</a></h3><p><code>FollowUser</code> 和 <code>UnfollowUser</code> 方法处理用户关系的状态转换。</p><ul><li>关注：在 <code>zfeed_follow</code> 中创建或更新一条记录，并设置 <code>Status=1</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/model/interaction_model.go#L37-L52" target="_blank" rel="noreferrer">app/rpc/interaction/internal/model/interaction_model.go#37-52</a></li><li>取消关注：将记录更新为 <code>Status=0</code>。</li><li>可靠性：与收藏类似，关注动作会触发事件；这些事件由 <code>count-rpc</code> 用于更新粉丝/关注数，也由 <code>content-rpc</code> 用于管理关注收件箱。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/proto/interaction.proto#L307-L314" target="_blank" rel="noreferrer">app/rpc/interaction/proto/interaction.proto#307-314</a></li></ul><h3 id="批量关注状态与摘要" tabindex="-1">批量关注状态与摘要 <a class="header-anchor" href="#批量关注状态与摘要" aria-label="Permalink to &quot;批量关注状态与摘要&quot;">​</a></h3><p>对于个人资料页和列表视图，服务提供优化后的查询方法：</p><ul><li>BatchQueryFollowing：一次调用中检查查看者是否关注了一组目标用户。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/proto/interaction.proto#L260-L272" target="_blank" rel="noreferrer">app/rpc/interaction/proto/interaction.proto#260-272</a></li><li>GetFollowSummary：返回总量计数（粉丝数/关注数）以及查看者与目标用户之间的具体关系。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/proto/interaction.proto#L274-L283" target="_blank" rel="noreferrer">app/rpc/interaction/proto/interaction.proto#274-283</a></li></ul><h3 id="图-follow-服务组件" tabindex="-1">图：Follow 服务组件 <a class="header-anchor" href="#图-follow-服务组件" aria-label="Permalink to &quot;图：Follow 服务组件&quot;">​</a></h3><p>将 gRPC 服务定义映射到内部逻辑和数据结构。</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/proto/interaction.proto#L307-L314" target="_blank" rel="noreferrer">app/rpc/interaction/proto/interaction.proto#307-314</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/model/interaction_model.go#L37-L52" target="_blank" rel="noreferrer">app/rpc/interaction/internal/model/interaction_model.go#37-52</a></p><h2 id="可靠投递-favoriteeventoutbox" tabindex="-1">可靠投递：FavoriteEventOutbox <a class="header-anchor" href="#可靠投递-favoriteeventoutbox" aria-label="Permalink to &quot;可靠投递：FavoriteEventOutbox&quot;">​</a></h2><p>为了确保互动计数最终一致，系统使用 Transactional Outbox。当收藏发生变化时，会向 <code>zfeed_favorite_event</code> 写入一条记录。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/model/interaction_model.go#L22-L35" target="_blank" rel="noreferrer">app/rpc/interaction/internal/model/interaction_model.go#22-35</a></p><ol><li>事件生成：<code>FavoriteLogic</code> 生成唯一 <code>EventID</code>，例如 <code>favorite_{user}_{content}_{timestamp}</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/favoritelogic.go#L96-L103" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/favoritelogic.go#96-103</a></li><li>下游消费：<code>count-rpc</code> 服务通过 Canal（MySQL Binlog）消费这些变化，并将更新应用到 <code>zfeed_count_value</code> 表。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/favorite_strategy.go#L25-L62" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/favorite_strategy.go#25-62</a></li><li>幂等性：下游消费者使用 <code>zfeed_mq_consume_dedup</code> 表确保每个 <code>EventID</code> 只被处理一次。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/repositories/mq_consume_dedup_repository_test.go#L18-L27" target="_blank" rel="noreferrer">app/rpc/interaction/internal/repositories/mq_consume_dedup_repository_test.go#18-27</a></li></ol><h3 id="count-rpc-中的收藏策略" tabindex="-1">Count-RPC 中的收藏策略 <a class="header-anchor" href="#count-rpc-中的收藏策略" aria-label="Permalink to &quot;Count-RPC 中的收藏策略&quot;">​</a></h3><p>计数服务中的 <code>favoriteStrategy</code> 会从 binlog 中提取更新。它识别操作类型（INSERT/DELETE/UPDATE），并为目标内容的收藏数计算 delta（+1 或 -1）。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/favorite_strategy.go#L38-L53" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/favorite_strategy.go#38-53</a></p><table tabindex="0"><thead><tr><th>操作</th><th>条件</th><th>Delta</th></tr></thead><tbody><tr><td>INSERT</td><td>状态为活跃</td><td>+1</td></tr><tr><td>DELETE</td><td>状态为活跃</td><td>-1</td></tr><tr><td>UPDATE</td><td>状态 0 -&gt; 1</td><td>+1</td></tr><tr><td>UPDATE</td><td>状态 1 -&gt; 0</td><td>-1</td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/count/internal/event/strategy/favorite_strategy.go#L15-L62" target="_blank" rel="noreferrer">app/rpc/count/internal/event/strategy/favorite_strategy.go#15-62</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/model/interaction_model.go#L22-L35" target="_blank" rel="noreferrer">app/rpc/interaction/internal/model/interaction_model.go#22-35</a></p><h2 id="查询与分页" tabindex="-1">查询与分页 <a class="header-anchor" href="#查询与分页" aria-label="Permalink to &quot;查询与分页&quot;">​</a></h2><h3 id="收藏列表分页" tabindex="-1">收藏列表分页 <a class="header-anchor" href="#收藏列表分页" aria-label="Permalink to &quot;收藏列表分页&quot;">​</a></h3><p><code>QueryFavoriteList</code> 方法使用基于 <code>FavoriteId</code>（收藏记录主键）的 cursor 分页。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go#L30-L75" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go#30-75</a></p><ul><li>请求：接收 <code>cursor</code> 和 <code>page_size</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/proto/interaction.proto#L109-L113" target="_blank" rel="noreferrer">app/rpc/interaction/proto/interaction.proto#109-113</a></li><li>仓储：调用 <code>ListContentByUserCursor</code> 获取 <code>pageSize + 1</code> 条记录，用于判断是否还有下一页。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go#L43-L48" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go#43-48</a></li><li>响应：将当前结果集中最后一项的 ID 作为 <code>next_cursor</code> 返回。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go#L65-L74" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go#65-74</a></li></ul><h3 id="收藏信息-计数与状态" tabindex="-1">收藏信息（计数与状态） <a class="header-anchor" href="#收藏信息-计数与状态" aria-label="Permalink to &quot;收藏信息（计数与状态）&quot;">​</a></h3><p><code>QueryFavoriteInfo</code> 逻辑首先使用 <code>BuildFavoriteRelKey</code> 构建 key，并在 Redis 中查询“是否收藏”状态。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/queryfavoriteinfologic.go#L61-L74" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/queryfavoriteinfologic.go#61-74</a> 如果缓存未命中，则查询数据库并带 TTL 回填缓存。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/queryfavoriteinfologic.go#L76-L91" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/queryfavoriteinfologic.go#76-91</a></p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go#L30-L75" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/queryfavoritelistlogic.go#30-75</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/interaction/internal/logic/favorite/queryfavoriteinfologic.go#L32-L59" target="_blank" rel="noreferrer">app/rpc/interaction/internal/logic/favorite/queryfavoriteinfologic.go#32-59</a></p>',38)])])}const h=t(a,[["render",n]]);export{b as __pageData,h as default};
